SELECT MAX(id)
  FROM sys_notify_user_message
 WHERE user_id = #{userId}

SELECT um.id, um.message_id, m.title, m.content, m.type, m.level, m.link_url,
       um.read_flag, um.read_time, m.create_time AS send_time
  FROM sys_notify_user_message um
  JOIN sys_notify_message m ON m.id = um.message_id
 WHERE um.user_id = #{userId}

    AND m.type = #{query.type}


    AND um.read_flag = #{query.readFlag}

 ORDER BY um.id DESC

SELECT id, message_id, user_id, read_flag, read_time, create_by, create_time, update_by, update_time
  FROM sys_notify_user_message
 WHERE id = #{id} AND user_id = #{userId}

mapper.update:
UPDATE sys_notify_user_message SET read_flag = 1, read_time = NOW()
, update_by = #{account}
, update_time = NOW() WHERE id = #{id} AND user_id = #{userId} AND read_flag = 0

